CREATE TABLE public.cleaning_visit_checks(visit_id uuid NOT NULL REFERENCES public.visits(id),pro_id uuid NOT NULL,checks jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(visit_id,pro_id));
GRANT SELECT ON public.cleaning_visit_checks TO authenticated; GRANT ALL ON public.cleaning_visit_checks TO service_role;
ALTER TABLE public.cleaning_visit_checks ENABLE ROW LEVEL SECURITY;
CREATE POLICY cleaning_checks_read ON public.cleaning_visit_checks FOR SELECT TO authenticated USING(public.pro_on_cleaning_team_visit(visit_id,auth.uid()) OR public.current_user_admin());
CREATE OR REPLACE FUNCTION public.pro_cleaning_checklist(_visit uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.visits; n integer; task text; checks jsonb; BEGIN IF NOT public.pro_on_cleaning_team_visit(_visit,auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO v FROM public.visits WHERE id=_visit; IF v.service::text<>'cleaning' THEN RETURN NULL; END IF; SELECT count(*) INTO n FROM public.visits WHERE user_id=v.user_id AND service::text='cleaning' AND status::text='complete' AND NOT coalesce(is_redo,false) AND id<>v.id AND visit_date<=v.visit_date; task:=(ARRAY['baseboards','blinds','fans_fixtures','cabinet_fronts','vents'])[mod(n,5)+1]; SELECT c.checks INTO checks FROM public.cleaning_visit_checks c WHERE visit_id=v.id AND pro_id=auth.uid(); RETURN jsonb_build_object('rotation',task,'checks',coalesce(checks,'{}'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.pro_cleaning_checklist(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pro_cleaning_checklist(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.pro_cleaning_check(_visit uuid,_key text,_checked boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.visits; BEGIN IF NOT public.pro_on_cleaning_team_visit(_visit,auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO v FROM public.visits WHERE id=_visit; IF v.service::text<>'cleaning' OR v.status::text NOT IN ('scheduled','on_the_way','in_progress') THEN RAISE EXCEPTION 'visit_not_open'; END IF; IF _key NOT IN ('touchpoints','stainless','glass','microwave','towels','shoe_covers','surface_safe','rotation','locked','alarm','lights_ac','keys_returned') OR _checked IS NULL THEN RAISE EXCEPTION 'invalid_check'; END IF; INSERT INTO public.cleaning_visit_checks(visit_id,pro_id,checks) VALUES(v.id,auth.uid(),jsonb_build_object(_key,_checked)) ON CONFLICT(visit_id,pro_id) DO UPDATE SET checks=cleaning_visit_checks.checks||excluded.checks,updated_at=now(); END $$;
REVOKE ALL ON FUNCTION public.pro_cleaning_check(uuid,text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pro_cleaning_check(uuid,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.cleaning_secure_exit_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE checks jsonb; BEGIN IF NEW.service::text='cleaning' AND NEW.status::text='complete' AND OLD.status::text<>'complete' AND NOT coalesce(NEW.is_sample,false) THEN SELECT c.checks INTO checks FROM public.cleaning_visit_checks c WHERE c.visit_id=NEW.id AND c.pro_id=NEW.assigned_pro_id; IF NOT coalesce(checks @> '{"locked":true,"alarm":true,"lights_ac":true,"keys_returned":true}'::jsonb,false) THEN RAISE EXCEPTION 'secure_exit_checklist_required'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER cleaning_secure_exit_guard BEFORE UPDATE OF status ON public.visits FOR EACH ROW EXECUTE FUNCTION public.cleaning_secure_exit_guard();